package ug.audiocity.studio;
import java.io.*;import java.nio.file.*;import java.util.*;
public final class AfroDrumPackTests {
 static int n;static void ok(boolean b,String why){n++;if(!b)throw new AssertionError(why);}static void clean(File f){if(f.isDirectory())for(File c:f.listFiles())clean(c);f.delete();}
 static SampledInstruments.Pack testPack(){SampledInstruments.Region[] r=new SampledInstruments.Region[14];for(int i=0;i<14;i++){float[] pcm=new float[200];Arrays.fill(pcm,(i+1)*.025f);r[i]=new SampledInstruments.Region(36+i,36+i,1,127,36+i,0,0,false,1,pcm,240);}return new SampledInstruments.Pack(AfroDrumPack.NAME,"Test personal pack; no factory license claim",r);}
 public static void main(String[] args)throws Exception{File root=Files.createTempDirectory("acs-afro-pack-").toFile();try{File app=new File(root,"app"),project=new File(root,"project"),input=new File(root,"input");app.mkdir();project.mkdir();input.mkdir();String payload=InstrumentArchive.write(testPack(),input);
  ok(!AfroDrumPack.available(project,app),"optional pack is absent before import");try{AfroDrumPack.load(project,app);throw new AssertionError("silent factory fallback");}catch(IOException expected){ok(expected.getMessage().contains("Import"),"missing pack explains how to import");}
  try(InputStream in=new FileInputStream(new File(input,payload))){AfroDrumPack.install(in,app);}ok(AfroDrumPack.available(project,app)&&AfroDrumPack.load(project,app).regions.length==14,"all 14 uploaded one-shots install and load");AfroDrumPack.copyToProject(app,project);SampledInstruments.Pack pack=AfroDrumPack.load(project,app);ok(new File(project,AfroDrumPack.FILE).isFile(),"chosen personal pack can travel with the project");
  BeatPilotDrumPattern p=new BeatPilotDrumPattern(240,1);for(int lane=0;lane<8;lane++){int choice=DrumSampleCatalog.afroChoice(lane,10);p.setSampleChoice(lane,choice);p.set(0,lane,lane,100);ok(choice==1010&&DrumSampleCatalog.isAfro(lane,choice),"stable reserved sample ID independent of factory list length");ok(DrumSampleCatalog.title(lane,choice).equals("VEDH Snare 024"),"picker keeps the original sample identity");ok(BeatPilotDrumPattern.decode(p.encode()).sampleChoice(lane)==1010,"personal choice survives pattern encoding");ok(p.resizedEmpty(4).sampleChoice(lane)==1010,"manual resizing preserves the personal sound");}ok(AfroDrumPack.used(p),"patterns detect personal sample dependencies");
  Core.Session s=new Core.Session();s.bpm=240;s.directory=project.getAbsolutePath();PatternLibrary.Entry e=PatternLibrary.add(s,"Afro",p);float[][] kit=new float[8][];for(int lane=0;lane<8;lane++)kit[lane]=pack.regions[10].pcm;PatternArrangement.place(s,e.id,kit,0,1);ok(ProjectIO.files(s).contains(AfroDrumPack.FILE),"project backup includes its selected Afro sample pack");ProjectIO.save(s);ByteArrayOutputStream backup=new ByteArrayOutputStream();AudioIO.backup(backup,s);File restored=new File(root,"restored");restored.mkdir();Core.Session reopened=AudioIO.restore(new ByteArrayInputStream(backup.toByteArray()),restored);new File(app,AfroDrumPack.FILE).delete();SampledInstruments.Pack portable=AfroDrumPack.load(restored,app);ok(portable.regions[10].pcm[0]==pack.regions[10].pcm[0],"restored patterns retain the original sound without global installation");ok(PatternLibrary.pattern(reopened,reopened.patterns.get(0)).sampleChoice(0)==1010,"sample selection survives project backup and reopen");
  try{AfroDrumPack.install(new ByteArrayInputStream(new byte[]{1,2,3}),app);throw new AssertionError("bad pack accepted");}catch(IOException expected){n++;}ok(!new File(app,AfroDrumPack.FILE).exists(),"invalid imports do not create a broken installed pack");
  System.out.println("AfroDrumPackTests passed "+n+" checks");
 }finally{clean(root);}}
}
